//! The host-integration schema agrees with the compiled types, and the status
//! and refusal rules a host relies on behave as documented.
//!
//! The schema file is generated by `scripts/generate_host_schema.py` from the
//! registries and enums that own each vocabulary. Every test here reads the
//! committed text and compares it with the values compiled into this build, so
//! a drift in either direction fails.
//!
//! SPDX-License-Identifier: MIT OR Apache-2.0

use std::collections::BTreeSet;

use antecedent::host::{
    HOST_CONTRACT_VERSION, HOST_SCHEMA_TEXT, HostStatus, claim_record, claim_response,
    error_family, error_response, host_schema, operation_record, refusal_code, refusal_record,
};
use antecedent::prelude::*;
use antecedent::{CausalError, RefuteSuite};
use antecedent_contract::{
    ClaimDomains, ClaimKind, DomainStatus, OperationKind, OperationReadiness, SemanticApplicability,
};
use serde_json::Value;

fn schema() -> Value {
    host_schema().expect("the committed schema is valid JSON")
}

fn enum_of(schema: &Value, name: &str) -> BTreeSet<String> {
    schema["$defs"][name]["enum"]
        .as_array()
        .unwrap_or_else(|| panic!("$defs.{name} is not an enumeration"))
        .iter()
        .map(|value| value.as_str().expect("enumeration members are strings").to_owned())
        .collect()
}

fn names<T: Copy>(all: &[T], name: fn(T) -> &'static str) -> BTreeSet<String> {
    all.iter().map(|value| name(*value).to_owned()).collect()
}

fn strings(list: &[&str]) -> BTreeSet<String> {
    list.iter().map(|code| (*code).to_owned()).collect()
}

#[test]
fn schema_declares_its_version_and_artifact_format() {
    let schema = schema();
    assert_eq!(schema["x-contract-version"], HOST_CONTRACT_VERSION);
    assert_eq!(schema["$id"], format!("urn:antecedent:host-contract:{HOST_CONTRACT_VERSION}"));
    assert_eq!(schema["x-artifact-format"]["major"], antecedent_io::STABLE_FORMAT.major);
    assert_eq!(schema["x-artifact-format"]["minor"], antecedent_io::STABLE_FORMAT.minor);
    assert!(HOST_SCHEMA_TEXT.ends_with('\n'));
}

#[test]
fn schema_vocabularies_equal_the_compiled_enums() {
    let schema = schema();
    assert_eq!(enum_of(&schema, "host_status"), names(&HostStatus::ALL, HostStatus::as_str));
    assert_eq!(enum_of(&schema, "claim_kind"), names(&ClaimKind::ALL, ClaimKind::as_str));
    assert_eq!(enum_of(&schema, "domain_status"), names(&DomainStatus::ALL, DomainStatus::as_str));
    assert_eq!(
        enum_of(&schema, "semantic_applicability"),
        names(&SemanticApplicability::ALL, SemanticApplicability::as_str)
    );
    assert_eq!(
        enum_of(&schema, "operation_readiness"),
        names(&OperationReadiness::ALL, OperationReadiness::as_str)
    );
    assert_eq!(
        enum_of(&schema, "operation_kind"),
        names(&OperationKind::ALL, OperationKind::as_str)
    );
    let cells = enum_of(&schema, "support_cell_status");
    for status in [
        antecedent::CellStatus::Licensed,
        antecedent::CellStatus::Refused,
        antecedent::CellStatus::NotApplicable { reason: "" },
    ] {
        assert!(cells.contains(status.as_str()), "{}", status.as_str());
    }
}

#[test]
fn schema_reason_codes_equal_the_generated_registry() {
    let schema = schema();
    assert_eq!(
        enum_of(&schema, "reason_code"),
        strings(antecedent_core::reason_code::REASON_CODES)
    );
    assert_eq!(
        enum_of(&schema, "refusal_code"),
        strings(antecedent_core::reason_code::RUNTIME_REFUSAL_CODES)
    );
}

fn failures() -> Vec<CausalError> {
    vec![
        antecedent::unsupported_reason!("attested_not_reverifiable", "names differ"),
        antecedent::support_reason!(
            "data_modality_not_licensed",
            "that cell is not licensed for this data modality"
        ),
        CausalError::Cancelled { stage: "identify" },
        CausalError::Resource { message: "scratch budget exceeded".into() },
        CausalError::Missing { field: "query" },
        CausalError::Compile { message: "the plan is not coherent".into() },
        CausalError::SchemaMismatch { detail: "column count".into() },
        CausalError::review_required_msg("orient the pending edges"),
        CausalError::not_identified(
            antecedent_core::IdentificationStatus::NotIdentified,
            false,
            "no adjustment set",
        ),
    ]
}

#[test]
fn every_error_family_a_failure_reports_is_in_the_schema() {
    let schema = schema();
    let families = enum_of(&schema, "error_family");
    for error in failures() {
        let family = error_family(&error);
        assert!(families.contains(family), "{family} for {error}");
    }
}

#[test]
fn error_families_are_stable_for_the_documented_failures() {
    let expected = [
        "unsupported",
        "unsupported",
        "cancelled",
        "resource",
        "compile",
        "compile",
        "data",
        "review_required",
        "not_identified",
    ];
    let got: Vec<&str> = failures().iter().map(error_family).collect();
    assert_eq!(got, expected);
}

#[test]
fn refusal_records_carry_only_registered_codes() {
    let schema = schema();
    let registered = enum_of(&schema, "refusal_code");
    let families = enum_of(&schema, "error_family");
    for error in failures() {
        let record = refusal_record(&error);
        assert_eq!(record["status"], "unsupported");
        assert!(families.contains(record["family"].as_str().unwrap()));
        if let Some(code) = record["reason_code"].as_str() {
            assert!(registered.contains(code), "{code}");
            assert_eq!(refusal_code(&error), Some(code));
        }
        assert_eq!(error_response(&error)["status"], "unsupported");
        assert_eq!(error_response(&error)["refusal"], record);
    }
    let coded = refusal_record(&antecedent::unsupported_reason!("not_executed", "no study"));
    assert_eq!(coded["reason_code"], "not_executed");
    assert_eq!(coded["family"], "unsupported");
}

fn domains(
    identification: DomainStatus,
    support: DomainStatus,
    evaluated: DomainStatus,
) -> ClaimDomains {
    ClaimDomains::new(identification, support, evaluated)
}

#[test]
fn claim_status_separates_supported_partial_and_unsupported() {
    use DomainStatus::{Contradicted, Evaluated, Identified, OutsideScope, Supported, Unknown};
    let full = domains(Identified, Supported, Evaluated);
    assert_eq!(HostStatus::of_claim_parts(ClaimKind::Point, &full), HostStatus::Supported);
    assert_eq!(HostStatus::of_claim_parts(ClaimKind::Response, &full), HostStatus::Supported);
    // An identified set and an open contract are partial answers, never values.
    assert_eq!(HostStatus::of_claim_parts(ClaimKind::Bounds, &full), HostStatus::Partial);
    assert_eq!(HostStatus::of_claim_parts(ClaimKind::Incomplete, &full), HostStatus::Partial);
    // No empirical check having run is visible in the domains but is not a failure.
    assert_eq!(
        HostStatus::of_claim_parts(ClaimKind::Point, &domains(Identified, Unknown, Evaluated)),
        HostStatus::Supported
    );
    // An unidentified or unevaluated claim is partial.
    assert_eq!(
        HostStatus::of_claim_parts(ClaimKind::Point, &domains(Identified, Supported, Unknown)),
        HostStatus::Partial
    );
    assert_eq!(
        HostStatus::of_claim_parts(ClaimKind::Point, &domains(Unknown, Supported, Evaluated)),
        HostStatus::Partial
    );
    // A refusal, a failed check and an out-of-scope coordinate are not usable.
    assert_eq!(HostStatus::of_claim_parts(ClaimKind::Refusal, &full), HostStatus::Unsupported);
    assert_eq!(
        HostStatus::of_claim_parts(ClaimKind::Point, &domains(Identified, Contradicted, Evaluated)),
        HostStatus::Unsupported
    );
    assert_eq!(
        HostStatus::of_claim_parts(
            ClaimKind::Bounds,
            &domains(Identified, OutsideScope, Evaluated)
        ),
        HostStatus::Unsupported
    );
}

#[test]
fn an_associational_claim_is_supported_as_noncausal_and_never_as_identified() {
    use DomainStatus::{Contradicted, Evaluated, Identified, NotClaimed, Supported, Unknown};
    let kind = ClaimKind::Associational;
    assert!(!kind.is_causal());
    // Identification not claimed and the association evaluated: a supported noncausal claim,
    // whether or not an empirical support check ran.
    for support in [Unknown, Supported] {
        assert_eq!(
            HostStatus::of_claim_parts(kind, &domains(NotClaimed, support, Evaluated)),
            HostStatus::Supported
        );
    }
    // An association never counts as an identified one, and an unevaluated one is partial.
    assert_eq!(
        HostStatus::of_claim_parts(kind, &domains(Identified, Supported, Evaluated)),
        HostStatus::Partial
    );
    assert_eq!(
        HostStatus::of_claim_parts(kind, &domains(NotClaimed, Supported, Unknown)),
        HostStatus::Partial
    );
    assert_eq!(
        HostStatus::of_claim_parts(kind, &domains(NotClaimed, Contradicted, Evaluated)),
        HostStatus::Unsupported
    );
    // A causal kind that does not claim identification is not supported by that.
    assert_eq!(
        HostStatus::of_claim_parts(ClaimKind::Point, &domains(NotClaimed, Supported, Evaluated)),
        HostStatus::Partial
    );
    assert_eq!(
        HostStatus::of_claim_names("associational", "not_claimed", "unknown", "evaluated"),
        Some(HostStatus::Supported)
    );
}

#[test]
fn claim_status_names_round_trip_and_refuse_unknown_names() {
    assert_eq!(
        HostStatus::of_claim_names("point", "identified", "supported", "evaluated"),
        Some(HostStatus::Supported)
    );
    assert_eq!(HostStatus::of_claim_names("point", "identified", "supported", "typo"), None);
    assert_eq!(
        HostStatus::of_claim_names("not_a_kind", "identified", "supported", "evaluated"),
        None
    );
}

#[test]
fn operation_status_follows_applicability_then_readiness() {
    use OperationReadiness as R;
    use SemanticApplicability as A;
    let of = HostStatus::of_operation_parts;
    assert_eq!(of(A::Licensed, Some(R::Executable)), HostStatus::Supported);
    for readiness in [
        R::ReviewRequired,
        R::AssumptionMissing,
        R::EmpiricalCheckPending,
        R::BindingMissing,
        R::RuntimeUnavailable,
        R::UnknownSupport,
    ] {
        assert_eq!(of(A::Licensed, Some(readiness)), HostStatus::Partial, "{readiness:?}");
    }
    assert_eq!(of(A::Licensed, Some(R::EmpiricalSupportFailed)), HostStatus::Unsupported);
    assert_eq!(of(A::Unlicensed, Some(R::Executable)), HostStatus::Unsupported);
    assert_eq!(of(A::Impossible, None), HostStatus::Unsupported);
    assert_eq!(of(A::Unknown, None), HostStatus::Partial);
    assert_eq!(
        HostStatus::of_operation_names("licensed", Some("executable")),
        Some(HostStatus::Supported)
    );
    assert_eq!(HostStatus::of_operation_names("licensed", Some("typo")), None);
}

/// The tiny linear study the identity regression suite also runs.
fn linear_study() -> (Study, TabularData) {
    let schema = CausalSchemaBuilder::new()
        .continuous("t")
        .treatment()
        .continuous("y")
        .outcome()
        .build()
        .unwrap();
    let treatment = [0.0, 1.0, 0.0, 1.0, 0.0, 1.0, 0.0, 1.0];
    let outcome = [1.0, 3.1, 0.9, 2.9, 1.0, 3.0, 1.1, 3.2];
    let columns: [(&str, &[f64]); 2] = [("t", &treatment), ("y", &outcome)];
    let data = TabularData::try_from_schema_f64(schema.clone(), columns).unwrap();
    let graph = Dag::from_named_edges(&schema, &[("t", "y")]).unwrap();
    let query =
        AverageEffectQuery::binary_ate(schema.id_of("t").unwrap(), schema.id_of("y").unwrap());
    let study = Study::tabular(data.clone())
        .graph(graph)
        .query(query)
        .refute(RefuteSuite::None)
        .bootstrap_replicates(0)
        .build()
        .unwrap();
    (study, data)
}

#[test]
fn a_real_claim_and_report_satisfy_the_schema_members() {
    let ctx = ExecutionContext::for_tests(3);
    let (study, data) = linear_study();
    let schema = schema();

    // Before preparing: the report is a record a host reads, not a result.
    let inspected = study.inspect().unwrap().capability();
    let before = operation_record(&inspected);
    assert!(enum_of(&schema, "host_status").contains(before["status"].as_str().unwrap()));
    assert!(enum_of(&schema, "operation_kind").contains(before["operation"].as_str().unwrap()));

    let prepared = study.prepare(&ctx).unwrap();
    let contract = prepared.contract().unwrap();
    let report = operation_record(&contract.capability());
    assert_eq!(report["status"], HostStatus::of_operation(&contract.capability()).as_str());

    let result = prepared.estimate(&data, &ctx).unwrap();
    let claim = result.claim(&contract, &ctx).unwrap();
    let record = claim_record(&claim);
    let required = schema["$defs"]["claim_envelope"]["required"].as_array().unwrap();
    for key in required {
        assert!(record.get(key.as_str().unwrap()).is_some(), "{key}");
    }
    assert!(enum_of(&schema, "claim_kind").contains(record["kind"].as_str().unwrap()));
    assert_eq!(record["status"], HostStatus::of_claim(&claim).as_str());
    assert_eq!(claim_response(&claim)["status"], record["status"]);
    assert_eq!(record["claim_id"].as_str().unwrap().len(), 64);
}
